import {useState, useEffect, use} from 'react';

export default function OwnedTickets() {
    const [tickets, setTickets] = useState([]);
    const token = localStorage.getItem("token");

    useEffect(() => {
        async function fetchTickets() {
            try {
                const response = await fetch("http://localhost:3001/ownedTickets", {
                    headers: {
                        "Authorization": `Bearer ${token}`
                    }
                });

                const data = await response.json();

                if (!response.ok) {
                    alert(`Sikertelen lekérdezés: ${data.message}`);
                } else {
                    setTickets(data.tickets);
                }
            } catch (err) {
                console.log(err);
                alert("Hiba történt a hibajegyek lekérése közben.");
            }
        }

        fetchTickets();
    }, []);

    return (
        <div className="container">
            <div className="card text-center">
            {tickets ? tickets.map(tickets => {
                return (
                <div className="card">
                    <div className="card-header">{tickets.title}</div>
                    <div className="card-body">
                        <h5 className="card-title">{}</h5>
                        <p className="card-text">With supporting text below as a natural lead-in to additional content.</p>
                        <a href="#" className="btn btn-primary">Törlés</a>
                    </div>
                    <div className="card-footer text-body-secondary">2 days ago</div>
                </div>
            )
            }) : (<p>Nincsenek hibajegyeid.</p>)}
        </div>
    </div>
    );
}
